"""ORACLE-338..342 unified one-build installer. Read-only shadow certification.
Requires installed local ORACLE-331, ORACLE-333, ORACLE-337, frozen ORACLE-322 bus.
Full new module, not a patch; no private key, no orders, no broadcasts.
"""
from __future__ import annotations
import argparse,hashlib,os,pathlib,py_compile,subprocess,sys,unittest,tempfile
from urllib.parse import urlsplit,quote
MODULE='qseries_v2.oracle_execution.solana_atomic_executor.oracle_343_unified_feed_recovery'
TARGET=pathlib.Path('qseries_v2/oracle_execution/solana_atomic_executor/oracle_343_unified_feed_recovery.py')
DEPENDENCIES=('qseries_v2/oracle_execution/solana_atomic_executor/boss_executor_live.py',
              'qseries_v2/oracle_execution/solana_atomic_executor/boss_ws_bank_requote.py',
              'qseries_v2/oracle_execution/solana_atomic_executor/boss_ws_full_account_witness.py')
